'use strict';
const byId=id=>document.getElementById(id);
const announce=text=>{byId('announcement').textContent=text;};
const views=['cases','mechanism','friction','inquiry'];
const conditions=['A genuine proximal improvement','Used to support a broader claim','Evidence for the broader purpose remains insufficient','Success helps close further inquiry'];
const cases={
 closure:{number:'01',title:'Fewer interruptions. A larger claim.',context:'A district introduces phone storage to reduce interruptions and support learning. Staff observations document fewer interruptions during lessons.',report:'“Interruptions have fallen. The policy has improved learning.”',decision:'The leadership team cites the improvement as its reason for canceling a planned review of student learning.',readingTitle:'A benefit is established. The learning claim is not.',reading:'Fewer interruptions support a claim about classroom conditions. They do not, alone, establish retention, transfer, or better understanding.',conditions:['Stipulated','Stipulated','Stipulated','Stipulated'],verdict:'An illustration of the proposed mechanism',limit:'All four conditions obtain here. A real study would need evidence connecting the improvement, its interpretation, and the decision to stop asking.',question:'What evidence would change this judgment?',detail:'Look for the original learning purpose, credible measures of interruptions, and records showing why the learning review was canceled.'},
 open:{number:'02',title:'Fewer interruptions. An open question.',context:'A district introduces the same phone storage policy. Staff observations document fewer interruptions, but the district has not yet examined durable learning.',report:'“Interruptions have fallen. We still need to examine what students are learning.”',decision:'The team continues its planned review of delayed explanations and student work. It considers changes in teaching and other possible explanations.',readingTitle:'A real benefit can support further inquiry.',reading:'The evidence is incomplete, but the team keeps the educational question open. Missing learning measures alone do not establish institutional unproductive success.',conditions:['Stipulated','Absent','Stipulated','Absent'],verdict:'A useful counterexample',limit:'The interpretation and closure conditions are absent. Continuing a credible inquiry is different from treating a proximal benefit as sufficient evidence of learning.',question:'What would make the inquiry credible?',detail:'Specify the learning purpose, suitable evidence, a review date, and who can change the instructional arrangements.'},
 social:{number:'03',title:'A different purpose. A bounded claim.',context:'A school restricts phones to reduce unwanted digital contact during the school day. Student reports and incident records indicate improvement on that stated purpose.',report:'“Reported unwanted contact during school has declined.”',decision:'The team makes no claim about academic learning. It continues to examine access, accommodations, and how different students experience the policy.',readingTitle:'Evaluate the purpose actually claimed.',reading:'Social and wellbeing purposes can be legitimate in their own right. They need appropriate evidence; they need not be reframed as academic learning outcomes.',conditions:['Stipulated','Absent','Not applicable','Absent'],verdict:'The proposed mechanism does not apply here',limit:'The case contains no substitution of a proximal benefit for a broader educational claim. The quality and limits of the social-outcome evidence still matter.',question:'Whose experience might the average obscure?',detail:'Examine the meaning of the reported improvement, differences across students, unintended effects, and the access arrangements supporting participation.'},
 failure:{number:'04',title:'An uneven rollout. No established benefit.',context:'Phone storage routines vary across classrooms. Exceptions are unclear, and available observations do not establish a reduction in interruptions.',report:'“Implementation remains inconsistent. We cannot yet establish the intended improvement.”',decision:'The team investigates capacity, routines, and accommodations before making an outcome claim.',readingTitle:'Not every incomplete reform has the same mechanism.',reading:'Institutional unproductive success requires a genuine proximal improvement. This case instead raises questions about implementation and whether any benefit has been established.',conditions:['Not established','Absent','Not established','Absent'],verdict:'Start with the implementation problem',limit:'Calling this unproductive success would skip a necessary condition. The framework should not become a label for every disappointing policy.',question:'What is actually happening in practice?',detail:'Compare the adopted policy with routines, exceptions, staff and student accounts, and credible observations of the intended proximal outcome.'}
};
let currentCase='closure';
function selectCase(key){if(!Object.hasOwn(cases,key))throw new Error('Unknown case');currentCase=key;const c=cases[key];for(const [id,field] of Object.entries({'case-number':'number','case-title':'title','case-context':'context','case-report':'report','case-decision':'decision','reading-title':'readingTitle','case-reading':'reading','case-verdict':'verdict','case-limit':'limit','case-question':'question','case-question-detail':'detail'}))byId(id).textContent=c[field];byId('case-conditions').replaceChildren(...conditions.map((text,i)=>{const row=document.createElement('div');row.className='condition';const label=document.createElement('span');label.textContent=text;const status=document.createElement('b');status.textContent=c.conditions[i];if(c.conditions[i]==='Stipulated')status.className='on';row.append(label,status);return row;}));document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===key)));announce(c.title);return {case:key,conditions:c.conditions,interpretation:c.verdict};}
const steps=[
 ['Regulate the object','Define what is restricted','The institution identifies an object to regulate, such as a personal phone, and states the purposes of restriction.','A district adopts phone storage during instructional time.','Read the policy, original purposes, scope, and exceptions. What problem does the policy claim to address?','A rule on paper does not establish implementation or any benefit.'],
 ['Organize the response','Make the policy administrable','Procedures, responsibilities, and reporting systems make the restriction visible and manageable.','Schools track storage compliance, enforcement, and reported interruptions.','Examine routines, responsibilities, accommodations, and the indicators used in reports.','Measures of compliance answer an implementation question. They do not automatically answer a learning question.'],
 ['Achieve a proximal benefit','Recognize a real improvement','A valued immediate condition improves. The argument depends on taking this benefit seriously.','Credible observations show fewer interruptions during lessons.','Is the improvement real? Which evidence supports it, for whom, and over what period?','The benefit may be worthwhile while its relationship to broader learning remains uncertain.'],
 ['Close the inquiry','Treat the benefit as sufficient','The improvement is interpreted as answering a broader educational question, helping bring further inquiry to a close.','Leaders cancel a planned learning review because the interruption data are treated as proof that learning improved.','Look for a sequence connecting improvement, interpretation, and a decision to stop or narrow inquiry.','Missing outcome measures alone are insufficient. The improvement must contribute to the closure of inquiry.'],
 ['Stabilize the arrangement','Make reopening harder','Roles, measures, routines, or resource commitments can reinforce the settled interpretation and make renewed inquiry more difficult.','Annual reports continue to prioritize compliance and interruptions, while no one has responsibility for the learning question.','Trace who owns the measures, who can revise the task or policy, and what would trigger a new review.','This is a proposed sequence to investigate, not an established universal trajectory or a prevalence estimate.']
];
byId('mechanism').innerHTML=`<div class="section-heading"><div><p class="eyebrow">FROM A BENEFIT TO A SETTLED ANSWER</p><h2 id="mechanism-title">When a real success closes a question.</h2></div><span class="tag">Proposed mechanism</span></div><p class="section-lead">Five moves help trace the institutional process. They are distinct from the four conditions that define the proposed construct.</p><div class="step-track" role="group" aria-label="Explore the five moves">${steps.map((s,i)=>`<button data-step="${i}" aria-pressed="false"><small>MOVE 0${i+1}</small>${s[0]}</button>`).join('')}</div><div class="mechanism-grid"><article class="mechanism-card"><p class="eyebrow" id="step-label"></p><h3 id="step-title"></h3><p id="step-body"></p><div class="example-box"><strong>A hypothetical example</strong><p id="step-example"></p></div><div class="pagination"><button id="previous-step">← Previous</button><span id="step-count"></span><button id="next-step">Next →</button></div></article><aside class="research-card"><p class="eyebrow">WHAT TO LOOK FOR</p><p id="step-look"></p><strong>Keep the inference bounded</strong><p id="step-caution"></p><div class="rule"><strong>Four conditions, considered together</strong><ol>${conditions.map(c=>`<li>${c}</li>`).join('')}</ol><p>This is a conceptual distinction, not a score or a validated checklist.</p></div></aside></div><details class="concept-note"><summary>How is this different from neighboring concepts?</summary><p>Kapur’s account of unproductive success concerns learner performance and learning. This article proposes an institutional extension: a real proximal success helps close inquiry into a broader purpose. Means–ends decoupling is a close conceptual neighbor. If this mechanism adds no explanatory value beyond that account, it should be treated as an application rather than a separate construct.</p></details>`;
let currentStep=0;
function selectStep(index){if(!Number.isInteger(index)||index<0||index>=steps.length)throw new Error('Move must be 1 through 5');currentStep=index;const s=steps[index];byId('step-label').textContent=`MOVE 0${index+1} / ${s[0].toUpperCase()}`;['step-title','step-body','step-example','step-look','step-caution'].forEach((id,i)=>byId(id).textContent=s[i+1]);byId('step-count').textContent=`${index+1} of 5`;byId('previous-step').disabled=index===0;byId('next-step').disabled=index===4;document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===index)));announce(s[1]);return {move:index+1,title:s[1],caution:s[5]};}
const lenses={
 noetic:['Noetic','Thinking, synthesis, judgment','Who performs the interpretive work?','A system supplies the interpretation before the learner has examined the sources.','The learner develops an initial interpretation, compares it with assistance, and explains which revisions are justified.','Novices may need background knowledge, worked examples, and accessible representations. Unsupported difficulty is not the objective.','Look for explanations, source comparisons, and justified revisions; use later tasks if making a durable-learning claim.'],
 rhetorical:['Rhetorical','Audience, challenge, response','Does the work meet a meaningful audience?','A polished product is accepted without questions about its reasoning or response to others.','The learner responds to a relevant objection, revises for an audience, and explains the revision.','Public exposure or anxiety is not itself educational. Offer accessible ways to participate and respond.','Look for how the learner addresses an objection and adapts a claim without losing responsibility for it.'],
 existential:['Existential','Responsibility for consequential choices','What does the learner remain answerable for?','A fluent product conceals who made the consequential choices and what their limits are.','The learner explains a consequential choice, its implications, and the limits of the claim they are willing to defend.','Responsibility does not require forced personal disclosure. Keep the task proportionate and offer appropriate boundaries.','Look for explanations of choices, consequences, uncertainty, and responsibility rather than polish alone.'],
 infrastructural:['Infrastructural','The conditions shaping the other three','What do the arrangements make possible?','A tool meets procurement requirements but supplies answers at a point where the task calls for interpretation.','Curriculum and technology staff jointly decide when assistance appears, what it supports, and who can revise the arrangement.','Accessible support can enable participation in the target work. Removing support and adding barriers is not the aim.','Examine defaults, permissions, timing, access, roles, and authority to change the task. These conditions do not themselves demonstrate learning.']
};
byId('friction').innerHTML=`<div class="section-heading"><div><p class="eyebrow">PEDAGOGICAL FRICTION</p><h2 id="friction-title">What work remains with the learner?</h2></div><span class="tag">Analytical lenses</span></div><p class="section-lead">The question is which encounters support the educational purpose. Difficulty is not inherently valuable, and accessibility support can make demanding work possible.</p><div class="friction-layout"><div class="lens-map"><h3>Three learner-facing encounters</h3><div class="learner-lenses">${['noetic','rhetorical','existential'].map(k=>`<button data-lens="${k}" aria-pressed="false"><strong>${lenses[k][0]}</strong><span>${lenses[k][1]}</span></button>`).join('')}</div><div class="base-connect" aria-hidden="true"></div><button data-lens="infrastructural" aria-pressed="false"><strong>Infrastructural</strong><span>The conditions shaping the other three</span></button><p class="base-caption">A conditioning base, not a fourth equivalent encounter.</p></div><article class="lens-detail"><p class="eyebrow" id="lens-label"></p><h3 id="lens-question"></h3><div class="task-pair"><div><h4>Where the work may be bypassed</h4><p id="lens-before"></p></div><div><h4>A possible task revision</h4><p id="lens-after"></p></div></div><div class="access-note"><strong>Access and support matter</strong><p id="lens-boundary"></p></div><div class="signal"><strong>What to examine</strong><p id="lens-signal"></p></div><p class="form-note">These are hypothetical design examples, not tested interventions.</p></article></div>`;
let currentLens='noetic';
function selectLens(key){if(!Object.hasOwn(lenses,key))throw new Error('Unknown lens');currentLens=key;const l=lenses[key];['lens-label','lens-question','lens-before','lens-after','lens-boundary','lens-signal'].forEach((id,i)=>byId(id).textContent=l[[0,2,3,4,5,6][i]]);document.querySelectorAll('[data-lens]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lens===key)));announce(l[2]);return {lens:key,question:l[2],boundary:l[5]};}
const evidence={
 implementation:['Implementation','Was the policy implemented?','Storage routines, enforcement records, exceptions, and staff and student accounts.','Implementation evidence cannot, by itself, establish educational outcomes.',['What differs between the written rule and daily practice?','Which exceptions and accommodations are working?','Whose account is absent from the implementation report?']],
 equity:['Access & equity','Who can participate, and under what conditions?','Accommodation access, translation, participation, disciplinary patterns, and the distribution of burdens.','Equitable implementation does not, by itself, establish a change in intellectual demand or learning.',['Who benefits and who carries added burdens?','Does support enable the intended intellectual work?','Which differences require a closer review?']],
 performance:['Immediate performance','What can students do under current conditions?','Completion, grades, participation, and products created with available assistance.','Immediate performance is not equivalent to retention or transfer.',['What assistance was available during the task?','What does the product reveal, and what does it conceal?','What would students need to explain beyond producing the answer?']],
 learning:['Durable learning','What persists or transfers?','Delayed explanations, performance under new conditions, and later tasks aligned with the learning purpose.','Evidence of durable learning does not, by itself, show that the device policy caused it.',['What should remain available after a delay?','Which new situation would meaningfully test transfer?','How will access supports be preserved while the target learning is examined?']],
 agency:['Agency & authorship','What judgment and responsibility remain with the learner?','Process evidence, explanations of choices, revisions, and responses to an audience.','Evidence of agency or authorship does not, by itself, establish a policy effect.',['Which consequential choices did the learner make?','Can the learner explain and revise those choices?','How does the task make assistance and responsibility visible?']],
 causation:['Causal attribution','Did the policy contribute to the change?','Comparative or longitudinal evidence that addresses timing, plausible counterfactuals, and alternative explanations.','A causal estimate does not, by itself, settle the educational value or equity of an outcome.',['What else changed in teaching, staffing, assessment, or student conditions?','What comparison would help distinguish a policy effect?','Which limitations remain in the explanation?']]
};
byId('inquiry').innerHTML=`<div class="section-heading"><div><p class="eyebrow">FROM A CLAIM TO A NEXT STEP</p><h2 id="inquiry-title">Match the question to the evidence.</h2></div><span class="tag">Your inquiry sheet</span></div><p class="section-lead no-print">Choose the question you actually need to answer. Use the prompts to prepare a focused review, then download your notes.</p><div class="inquiry-grid"><div class="question-picker no-print" role="group" aria-label="Choose an evaluation question">${Object.entries(evidence).map(([k,e],i)=>`<button data-evidence="${k}" aria-pressed="false">0${i+1} &nbsp; ${e[0]}</button>`).join('')}</div><article class="evidence-card"><p class="eyebrow">EVIDENCE AND ITS LIMITS</p><h3 id="evidence-question"></h3><div class="evidence-columns"><div><h4>Evidence suited to this question</h4><p id="evidence-suited"></p></div><div><h4>What it cannot establish alone</h4><p id="evidence-limit"></p></div></div><h4>Questions for the review</h4><ul id="evidence-prompts"></ul><form id="reflection-form" class="reflection-form no-print"><p class="eyebrow">MAKE THE NEXT INQUIRY CONCRETE</p><label for="claim">What specific claim are you reviewing?<textarea id="claim" rows="2" maxlength="3000" placeholder="For example: Fewer interruptions mean students are learning more."></textarea></label><label for="known">What is known, and what remains uncertain?<textarea id="known" rows="3" maxlength="5000"></textarea></label><label for="next">What evidence will you examine next?<textarea id="next" rows="3" maxlength="5000" placeholder="Include what could challenge the claim and whose access or experience needs attention."></textarea></label><div class="form-pair"><label for="owner">Who can act on the findings?<input id="owner" maxlength="300" placeholder="A role or team"></label><label for="when">When will the question be revisited?<input id="when" maxlength="300" placeholder="A date or decision point"></label></div><p class="form-note">Your notes stay in this page while it is open. Download them before reloading or leaving. Use roles and anonymized examples rather than identifiable student or participant information.</p><div class="form-actions"><button id="download" class="action-button" type="button">Download inquiry (.md) ↓</button><button id="print" class="action-button secondary" type="button">Print inquiry</button></div><p id="download-status" class="empty-status" role="status"></p></form><div id="print-summary" class="print-summary"></div></article></div>`;
let currentEvidence='implementation';
function selectEvidence(key){if(!Object.hasOwn(evidence,key))throw new Error('Unknown evaluation question');currentEvidence=key;const e=evidence[key];byId('evidence-question').textContent=e[1];byId('evidence-suited').textContent=e[2];byId('evidence-limit').textContent=e[3];byId('evidence-prompts').replaceChildren(...e[4].map(p=>{const li=document.createElement('li');li.textContent=p;return li;}));document.querySelectorAll('[data-evidence]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.evidence===key)));announce(e[1]);return {question:e[1],evidence:e[2],limit:e[3]};}
function reflection(){const e=evidence[currentEvidence];return ['# Reclaimed Attention: Inquiry Sheet','',`Evaluation question: ${e[1]}`,'','## Evidence suited to the question',e[2],'','## Limits of the inference',e[3],'','## Questions for the review',...e[4].map(p=>`- ${p}`),'',...Object.entries({claim:'Claim under review',known:'Known and uncertain',next:'Next evidence to examine',owner:'Responsibility and authority',when:'Review point'}).flatMap(([id,label])=>[`## ${label}`,byId(id).value.trim()||'Not yet specified','']),'---','Companion to Micah J. Miner’s conceptual manuscript, Reclaimed Attention Is Not a Learning Outcome: Institutional Unproductive Success in K–12 Device Restriction.','This reflection is a planning aid, not a validated diagnostic instrument or evidence of a causal effect.',''].join('\n');}
byId('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([reflection()],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='reclaimed-attention-inquiry.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);byId('download-status').textContent='Download requested. If your browser blocks it, use Print inquiry to save a PDF.';});
byId('print').addEventListener('click',()=>{byId('print-summary').textContent=reflection();window.print();});
window.addEventListener('beforeprint',()=>{byId('print-summary').textContent=reflection();});
byId('reflection-form').addEventListener('submit',e=>e.preventDefault());
const showSheet=document.createElement('button');showSheet.type='button';showSheet.className='action-button secondary';showSheet.textContent='View inquiry text';byId('download').parentElement.append(showSheet);
const sheetPreview=document.createElement('textarea');sheetPreview.readOnly=true;sheetPreview.rows=14;sheetPreview.hidden=true;sheetPreview.setAttribute('aria-label','Inquiry sheet text to copy');byId('reflection-form').append(sheetPreview);showSheet.addEventListener('click',()=>{sheetPreview.value=reflection();sheetPreview.hidden=false;sheetPreview.focus();sheetPreview.select();announce('Inquiry text is ready to copy.');});
byId('source-content').innerHTML=`<p>Adapted from Micah J. Miner’s conceptual manuscript, <em>Reclaimed Attention Is Not a Learning Outcome: Institutional Unproductive Success in K–12 Device Restriction</em>. This companion illustrates the argument; it does not report a study of these cases or establish the construct’s prevalence.</p><p>The institutional mechanism is drawn from Section 5; the friction lenses from Sections 4 and 7; and the evaluation questions from Section 8, Table 1. Scenarios and task revisions are newly written, hypothetical illustrations.</p><p>Conceptual neighbors and foundations include <a href="https://doi.org/10.1080/00461520.2016.1155457" target="_blank" rel="noopener noreferrer">Kapur (2016), unproductive success</a>; <a href="https://doi.org/10.1177/1745691615569000" target="_blank" rel="noopener noreferrer">Soderstrom and Bjork (2015), learning and performance</a>; and <a href="https://doi.org/10.1080/19416520.2012.684462" target="_blank" rel="noopener noreferrer">Bromley and Powell (2012), organizational decoupling</a>.</p><p>No numerical score, threshold, or intervention here has been validated. A case judgment requires evidence, including evidence that could challenge the interpretation. The inquiry form sends no notes to a server and uses no browser storage or AI service.</p>`;
function navigate(focus=false){const key=location.hash.slice(1);const active=views.includes(key)?key:'cases';document.querySelectorAll('.view').forEach(el=>{el.hidden=el.id!==active;});document.querySelectorAll('.chapters a').forEach(el=>{if(el.hash==='#'+active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});if(focus&&views.includes(key)){const title=byId(active+'-title');title.tabIndex=-1;title.focus({preventScroll:true});}return active;}
document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>selectCase(b.dataset.case)));
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>selectStep(Number(b.dataset.step))));
document.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>selectLens(b.dataset.lens)));
document.querySelectorAll('[data-evidence]').forEach(b=>b.addEventListener('click',()=>selectEvidence(b.dataset.evidence)));
byId('previous-step').addEventListener('click',()=>selectStep(currentStep-1));byId('next-step').addEventListener('click',()=>selectStep(currentStep+1));
window.addEventListener('hashchange',()=>navigate(true));selectCase('closure');selectStep(0);selectLens('noetic');selectEvidence('implementation');navigate();byId('announcement').textContent='';
if(document.modelContext?.registerTool){const controller=new AbortController();try{document.modelContext.registerTool({name:'explore_companion',description:'Explore this conceptual reader companion. Sections: cases (selection closure, open, social, failure), mechanism (selection 1 through 5), friction (selection noetic, rhetorical, existential, infrastructural), inquiry (selection implementation, equity, performance, learning, agency, causation). Changes only the displayed section and selection; does not alter notes.',inputSchema:{type:'object',properties:{section:{type:'string',enum:views},selection:{type:'string'}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,destructiveHint:false},execute:async({section,selection})=>{if(!views.includes(section))throw new Error('Unknown section');let result;if(selection!==undefined){if(section==='cases')result=selectCase(selection);if(section==='mechanism'){if(!/^[1-5]$/.test(selection))throw new Error('Select move 1 through 5');result=selectStep(Number(selection)-1);}if(section==='friction')result=selectLens(selection);if(section==='inquiry')result=selectEvidence(selection);}location.hash=section;navigate();return {content:[{type:'text',text:JSON.stringify({section,...result})}]};}},{signal:controller.signal});document.modelContext.registerTool({name:'read_inquiry_reflection',description:'Read the current inquiry sheet, including any notes the user entered on this page. Returns text only; does not save or transmit a file.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({content:[{type:'text',text:reflection()}]})},{signal:controller.signal});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}catch(error){console.warn('Optional companion tools unavailable:',error.message);}}
